        assert test_stable_e is False

        S = mf.get_ovlp()
        I = cp.eye(ref_mo_i_1.shape[-1])[None, :, :]

        diff_i1 = cp.max(cp.abs(cp.abs(cp.einsum("upi,pq,uqj->uij", ref_mo_i_1, S, test_mo_i)) - I))
