        assert diff_i1 < 4e-3 or diff_i2 < 4e-3

        S = block_diag(S, S)
        I = cp.eye(test_mo_i.shape[-1] * 2)

        diff_ea1 = cp.max(cp.abs(cp.abs(ref_mo_e_1.T @ S @ test_mo_e) - I))
        diff_ea2 = cp.max(cp.abs(cp.abs(ref_mo_e_2.T @ S @ test_mo_e) - I))
        assert diff_ea1 < 4e-3 or diff_ea2 < 4e-3

